```go
package main

import (
    "fmt"
    "strconv"
)

func parsePort(text string) (int, error) {
    return strconv.Atoi(text)
}

func main() {
    port, err := parsePort("8080")
    fmt.Println(port, err)

    port, err = parsePort("abc")
    fmt.Println(port, err != nil)
}
```
The valid call produces `8080 <nil>`; the invalid call produces zero plus `true` for the error check.

```go
package main

import (
    "errors"
    "fmt"
)

type User struct{ Name string }

func loadUser(found bool) (*User, error) {
    if !found {
        return nil, errors.New("user not found")
    }
    return &User{Name: "Ada"}, nil
}

func main() {
    user, err := loadUser(false)
    fmt.Println(user == nil, err != nil)
}
```
Both printed values are `true`, giving the failure path a clear and testable invariant.

```go
package main

import (
    "fmt"
    "io"
)

type finalChunk struct{ done bool }

func (r *finalChunk) Read(p []byte) (int, error) {
    if r.done {
        return 0, io.EOF
    }
    r.done = true
    return copy(p, "go"), io.EOF
}

func main() {
    reader := &finalChunk{}
    buf := make([]byte, 4)
    n, err := reader.Read(buf)
    if n > 0 {
        fmt.Println(string(buf[:n]))
    }
    fmt.Println(err == io.EOF)
}
```
The program prints `go` before `true`; checking EOF first would have thrown away valid data.
